// The id the MDRepo client and the mock backend hand out: an InvenioRDM-style identifier (letters, digits, "-" and "_").
// Route params are checked with this before they reach an href, the `next` parameter or a backend call (security
// finding on [draftId]). TODO(backend): widen or narrow once the real id format is confirmed (backend doc section 5, item 3).
const DRAFT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;

const isDraftId = (value: unknown): value is string => typeof value === "string" && DRAFT_ID_PATTERN.test(value);

// Run ids are generated by this app (or by the backend) with the same alphabet.
const RUN_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

const isRunId = (value: unknown): value is string => typeof value === "string" && RUN_ID_PATTERN.test(value);

const newRunId = (): string => `run-${crypto.randomUUID().slice(0, 8)}`;

type WizardTarget = "study" | "system" | "experiments" | "review";

// Always encodes: callers never build wizard URLs by string concatenation.
const draftHref = (draftId: string, target?: WizardTarget, runId?: string): string => {
  const base = `/depositions/${encodeURIComponent(draftId)}`;
  if (!target) return base;
  return runId === undefined ? `${base}/${target}` : `${base}/${target}/${encodeURIComponent(runId)}`;
};

export { draftHref, isDraftId, isRunId, newRunId };
export type { WizardTarget };
